import{_ as a,o as i,c as l,a2 as t}from"./chunks/framework.XXezeKOl.js";const h=JSON.parse('{"title":"零基础入门路径","description":"面向没有编程经验或只会一点脚本的学习者，约 16 周，从搭环境到交付一个可用的知识库 Agent。","frontmatter":{"title":"零基础入门路径","description":"面向没有编程经验或只会一点脚本的学习者，约 16 周，从搭环境到交付一个可用的知识库 Agent。"},"headers":[],"relativePath":"roadmap/beginner.md","filePath":"roadmap/beginner.md","lastUpdated":null}'),r={name:"roadmap/beginner.md"};function n(o,e,p,s,g,d){return i(),l("div",null,[...e[0]||(e[0]=[t(`<h1 id="零基础入门路径" tabindex="-1">零基础入门路径 <a class="header-anchor" href="#零基础入门路径" aria-label="Permalink to &quot;零基础入门路径&quot;">​</a></h1><p>这条路径适合没写过程序、或者只写过少量脚本的同学。节奏按每周投入 8 到 10 小时估算，总共约 16 周。前 4 周看起来和 Agent 没什么关系，但它决定了你后面能不能自己调通代码，请不要跳过。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 1-4 周         第 5-7 周          第 8-10 周          第 11-14 周           第 15-16 周</span></span>
<span class="line"><span>基础准备   ──▶   大模型与提示词 ──▶ Tool Calling   ──▶  上下文/记忆/RAG ──▶  评估与安全入门</span></span>
<span class="line"><span>                                   与 Agent 循环        /MCP</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">语言选择</p><p>零基础建议只学 Python。文章里的 Go / Java 代码标签页可以先忽略，等你熟练后再回头看。</p></div><h2 id="阶段-1-基础准备-第-1-4-周" tabindex="-1">阶段 1：基础准备（第 1-4 周） <a class="header-anchor" href="#阶段-1-基础准备-第-1-4-周" aria-label="Permalink to &quot;阶段 1：基础准备（第 1-4 周）&quot;">​</a></h2><p>目标：能独立写一个调用 HTTP 接口、解析 JSON、处理错误的 Python 小程序。</p><p>必读：</p><ul><li><a href="/guide/00-intro/what-is-agent">Agent 到底是什么</a></li><li><a href="/guide/00-intro/agent-vs-workflow">Agent、Chatbot 与 Workflow 的区别</a></li><li><a href="/guide/00-intro/how-to-learn">如何使用本站学习</a></li><li><a href="/guide/01-programming/dev-env">开发环境：Python / Go / Java</a>（只看 Python 部分）</li><li><a href="/guide/01-programming/python-essentials">Agent 开发必备 Python</a>：建议配合任意一门 Python 入门教程，花 2 周把基础语法练熟</li><li><a href="/guide/01-programming/http-json">HTTP、JSON 与 REST API</a></li><li><a href="/guide/01-programming/data-validation">数据校验：pydantic / struct tag / record</a>（只看 pydantic）</li></ul><p>可以先跳过：<a href="/guide/01-programming/async">异步与并发编程</a>、<a href="/guide/01-programming/streaming-sse">流式输出与 SSE</a>，阶段 2 用到时再读。</p><p>练习：用 <code>requests</code> 或 <code>httpx</code> 调用一个公开 API（比如天气或汇率），把结果整理成表格打印出来。</p><p>自检清单：</p><ul><li>[ ] 能创建虚拟环境、安装依赖、运行一个 <code>.py</code> 文件</li><li>[ ] 理解 list、dict、函数、类、异常处理的基本用法</li><li>[ ] 能说清一个 HTTP 请求由哪几部分组成（方法、URL、Header、Body）</li><li>[ ] 能把一段 JSON 字符串解析成 Python 对象，并取出嵌套字段</li><li>[ ] 知道 API Key 不能写死在代码里，会用环境变量读取</li></ul><h2 id="阶段-2-大模型与提示词-第-5-7-周" tabindex="-1">阶段 2：大模型与提示词（第 5-7 周） <a class="header-anchor" href="#阶段-2-大模型与提示词-第-5-7-周" aria-label="Permalink to &quot;阶段 2：大模型与提示词（第 5-7 周）&quot;">​</a></h2><p>目标：理解大模型的基本工作方式，能写出一个多轮对话的命令行聊天程序，并让模型稳定输出 JSON。</p><p>必读：</p><ul><li><a href="/guide/02-llm-basics/transformer">Transformer 的直觉理解</a></li><li><a href="/guide/02-llm-basics/tokens-context">Token 与上下文窗口</a></li><li><a href="/guide/02-llm-basics/sampling">采样参数：temperature、top_p</a></li><li><a href="/guide/03-llm-api/first-call">第一次调用大模型</a></li><li><a href="/guide/03-llm-api/multi-turn">多轮对话与消息结构</a></li><li><a href="/guide/03-llm-api/streaming">流式响应实战</a>（此时回头读 <a href="/guide/01-programming/streaming-sse">流式输出与 SSE</a>）</li><li><a href="/guide/03-llm-api/cost-errors">计费、限流与错误重试</a></li><li><a href="/guide/04-prompt/basics">提示词基本原则</a></li><li><a href="/guide/04-prompt/system-prompt">系统提示词与角色设计</a></li><li><a href="/guide/04-prompt/few-shot-cot">Few-shot 与思维链</a></li><li><a href="/guide/04-prompt/structured-output">结构化输出与 JSON Schema</a></li></ul><p>可以先跳过：<a href="/guide/02-llm-basics/reasoning-models">推理模型与扩展思考</a>、<a href="/guide/03-llm-api/multimodal">多模态输入</a>、<a href="/guide/04-prompt/prompt-management">提示词版本管理与测试</a>。</p><p>项目：<a href="/projects/01-cli-chat">01 命令行聊天助手</a></p><p>自检清单：</p><ul><li>[ ] 能解释 Token 是什么，以及为什么对话太长会出错</li><li>[ ] 知道 temperature 调高、调低分别会带来什么效果</li><li>[ ] 能说出 system / user / assistant 三种角色的作用</li><li>[ ] 理解&quot;模型没有记忆，多轮对话靠每次把历史消息重新发过去&quot;</li><li>[ ] 能写出一个让模型返回固定 JSON 格式的提示词，并用 pydantic 校验结果</li><li>[ ] 遇到 429 或超时错误时，知道应该重试并加退避</li></ul><h2 id="阶段-3-tool-calling-与-agent-循环-第-8-10-周" tabindex="-1">阶段 3：Tool Calling 与 Agent 循环（第 8-10 周） <a class="header-anchor" href="#阶段-3-tool-calling-与-agent-循环-第-8-10-周" aria-label="Permalink to &quot;阶段 3：Tool Calling 与 Agent 循环（第 8-10 周）&quot;">​</a></h2><p>目标：让模型能调用你写的函数，并亲手写出一个不依赖框架的 Agent 循环。</p><p>必读：</p><ul><li><a href="/guide/05-tool-calling/concept">工具调用原理</a></li><li><a href="/guide/05-tool-calling/first-tool">实现第一个工具</a></li><li><a href="/guide/05-tool-calling/tool-design">工具设计原则</a></li><li><a href="/guide/05-tool-calling/error-handling">工具错误处理与重试</a></li><li><a href="/guide/06-agent-loop/react">ReAct：推理与行动</a></li><li><a href="/guide/06-agent-loop/handwritten-agent">不用框架手写 Agent</a></li><li><a href="/guide/06-agent-loop/stop-budget">终止条件、步数与预算控制</a></li><li><a href="/guide/14-evaluation/why-evals">为什么评估是第一优先级</a>（提前建立评估意识）</li></ul><p>可以先跳过：<a href="/guide/05-tool-calling/parallel-tools">并行工具调用</a>、<a href="/guide/06-agent-loop/plan-execute">Plan-and-Execute</a>、<a href="/guide/06-agent-loop/reflection">Reflection 自我反思</a>。</p><p>项目：<a href="/projects/02-tool-agent">02 天气日程工具 Agent</a>，学有余力再做 <a href="/projects/03-react-agent">03 手写 ReAct Agent</a>。</p><p>自检清单：</p><ul><li>[ ] 能讲清：模型只负责&quot;决定调用哪个工具、传什么参数&quot;，真正执行的是你的代码</li><li>[ ] 能为一个函数写出清晰的工具描述和参数 JSON Schema</li><li>[ ] 能画出 Agent 循环：调用模型 → 执行工具 → 把结果放回消息 → 再次调用模型</li><li>[ ] 知道为什么必须设置最大步数</li><li>[ ] 工具报错时，知道把错误信息返回给模型而不是让程序崩溃</li></ul><h2 id="阶段-4-上下文、记忆、rag-与-mcp-第-11-14-周" tabindex="-1">阶段 4：上下文、记忆、RAG 与 MCP（第 11-14 周） <a class="header-anchor" href="#阶段-4-上下文、记忆、rag-与-mcp-第-11-14-周" aria-label="Permalink to &quot;阶段 4：上下文、记忆、RAG 与 MCP（第 11-14 周）&quot;">​</a></h2><p>目标：让 Agent 能基于你自己的文档回答问题，并了解 MCP 如何把工具标准化。</p><p>必读：</p><ul><li><a href="/guide/07-context-engineering/overview">什么是上下文工程</a></li><li><a href="/guide/07-context-engineering/window-management">上下文窗口管理</a></li><li><a href="/guide/08-memory/memory-types">记忆的分类</a></li><li><a href="/guide/08-memory/short-term">短期记忆与会话管理</a></li><li><a href="/guide/02-llm-basics/embeddings">Embedding 与向量语义</a></li><li><a href="/guide/09-rag/overview">RAG 全景</a></li><li><a href="/guide/09-rag/chunking">文档解析与切分</a></li><li><a href="/guide/09-rag/vector-db">向量数据库</a></li><li><a href="/guide/10-mcp/mcp-overview">MCP 架构与核心概念</a></li><li><a href="/guide/10-mcp/mcp-server">开发一个 MCP Server</a></li><li><a href="/guide/11-frameworks/overview">框架全景与选型</a></li></ul><p>可以先跳过：压缩与摘要、Prompt Caching、长期记忆、混合检索与重排、GraphRAG、A2A，以及框架模块里除总览外的文章。</p><p>项目：<a href="/projects/04-pdf-rag">04 个人 PDF 知识库</a>，然后 <a href="/projects/05-mcp-server">05 开发自己的 MCP Server</a>。</p><p>自检清单：</p><ul><li>[ ] 能说清&quot;上下文窗口有限&quot;对 Agent 设计意味着什么</li><li>[ ] 能解释 Embedding 为什么能做语义搜索</li><li>[ ] 能画出 RAG 的两条链路：离线建索引、在线检索加生成</li><li>[ ] 知道切分块太大、太小分别有什么问题</li><li>[ ] 能说出 MCP 里 Host、Client、Server 的关系</li><li>[ ] 自己的 PDF 知识库能回答文档里的问题，并给出引用来源</li></ul><h2 id="阶段-5-评估与安全入门-第-15-16-周" tabindex="-1">阶段 5：评估与安全入门（第 15-16 周） <a class="header-anchor" href="#阶段-5-评估与安全入门-第-15-16-周" aria-label="Permalink to &quot;阶段 5：评估与安全入门（第 15-16 周）&quot;">​</a></h2><p>目标：零基础路径不追求掌握全部生产化内容，重点是建立评估和安全意识，为后续进阶打底。</p><p>必读：</p><ul><li><a href="/guide/14-evaluation/eval-design">评估集与指标设计</a></li><li><a href="/guide/14-evaluation/llm-judge">LLM-as-Judge</a></li><li><a href="/guide/15-production/prompt-injection">Prompt 注入与防护</a></li><li><a href="/guide/15-production/permissions-hitl">权限控制与人在环路</a></li><li><a href="/guide/12-multi-agent/why-multi-agent">为什么需要多 Agent</a></li></ul><p>可以先跳过：多 Agent 编排细节、Coding Agent、服务化与部署，完成本路径后转入 <a href="/roadmap/engineer">工程师路径</a> 的阶段 4、5 继续学习。</p><p>项目：为阶段 4 的 PDF 知识库写一个 20 条左右的评估集，并加上 Prompt 注入防护，或者完成 <a href="/projects/06-research-agent">06 网页研究员 Agent</a>。</p><p>自检清单：</p><ul><li>[ ] 能为自己的 Agent 写出至少 20 条带期望答案的测试用例</li><li>[ ] 能解释 LLM-as-Judge 的用途和它的偏差风险</li><li>[ ] 能举例说明什么是间接 Prompt 注入</li><li>[ ] 知道哪些工具操作应该让人确认后再执行</li><li>[ ] 能判断一个需求是否真的需要多 Agent</li></ul><p>完成后，你已经具备独立开发一个简单 Agent 应用的能力。下一步建议对照 <a href="/roadmap/12-weeks">12 周学习计划</a> 的第 10-12 周查漏补缺，或者直接挑战 <a href="/projects/10-enterprise-assistant">10 毕业项目：企业知识助手</a>。</p>`,45)])])}const c=a(r,[["render",n]]);export{h as __pageData,c as default};
